async function retry(fn, attempts) {
  return fn();
}

module.exports = { retry };

files.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('./solution');

test('retries until success without exceeding the limit', async () => {
  let calls = 0;
  const value = await retry(async () => {
    calls += 1;
    if (calls < 3) throw new Error('transient');
    return 'ok';
  }, 4);
  assert.equal(value, 'ok');
  assert.equal(calls, 3);
});

test('throws the final error after all attempts', async () => {
  let calls = 0;
  await assert.rejects(
    retry(async () => {
      calls += 1;
      throw new Error(`failure-${calls}`);
    }, 2),
    /failure-2/
  );
  assert.equal(calls, 2);
});

test('rejects invalid attempt counts', async () => {
  await assert.rejects(retry(async () => 'x', 0), /attempts/i);
});

