function mergeConfig(defaults, overrides) {
  return { ...defaults, ...overrides };
}

module.exports = { mergeConfig };

files.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('./solution');

test('recursively preserves unspecified nested defaults', () => {
  const defaults = { database: { host: 'db.local', port: 5432 }, flags: ['a'], retries: 3 };
  const overrides = { database: { host: 'prod.db' }, flags: ['b'] };
  assert.deepEqual(mergeConfig(defaults, overrides), {
    database: { host: 'prod.db', port: 5432 },
    flags: ['b'],
    retries: 3
  });
});

test('ignores undefined override values and does not mutate inputs', () => {
  const defaults = { retries: 3, nested: { enabled: true } };
  const overrides = { retries: undefined, nested: { enabled: false } };
  const result = mergeConfig(defaults, overrides);
  assert.deepEqual(result, { retries: 3, nested: { enabled: false } });
  assert.deepEqual(defaults, { retries: 3, nested: { enabled: true } });
  assert.deepEqual(overrides, { retries: undefined, nested: { enabled: false } });
});

