function orderJobs(jobs) {
  return jobs.map((job) => job.id);
}

module.exports = { orderJobs };

files.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const { orderJobs } = require('./solution');

test('orders dependencies before dependents with stable readiness order', () => {
  const jobs = [
    { id: 'deploy', deps: ['build', 'test'] },
    { id: 'lint', deps: [] },
    { id: 'build', deps: [] },
    { id: 'test', deps: ['build'] }
  ];
  assert.deepEqual(orderJobs(jobs), ['lint', 'build', 'test', 'deploy']);
});

test('detects cycles', () => {
  assert.throws(() => orderJobs([
    { id: 'a', deps: ['b'] },
    { id: 'b', deps: ['a'] }
  ]), /cycle/i);
});

test('rejects unknown dependency IDs', () => {
  assert.throws(() => orderJobs([{ id: 'a', deps: ['missing'] }]), /unknown|missing/i);
});

