async function mapLimit(items, limit, mapper) {
  return Promise.all(items.map(mapper));
}

module.exports = { mapLimit };

files.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('./solution');

test('respects concurrency and preserves result order', async () => {
  let active = 0;
  let maxActive = 0;
  const result = await mapLimit([1, 2, 3, 4, 5, 6], 2, async (value) => {
    active += 1;
    maxActive = Math.max(maxActive, active);
    await new Promise((resolve) => setTimeout(resolve, value % 2 ? 12 : 2));
    active -= 1;
    return value * 10;
  });
  assert.deepEqual(result, [10, 20, 30, 40, 50, 60]);
  assert.ok(maxActive <= 2, `observed concurrency ${maxActive}`);
});

test('rejects invalid limits', async () => {
  await assert.rejects(mapLimit([1], 0, async (x) => x), /limit/i);
});

