function canDelete(actor, target) {
  return Boolean(actor && target && actor.orgId === target.orgId);
}

module.exports = { canDelete };

files.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const { canDelete } = require('./solution');

const target = { ownerId: 'owner', orgId: 'org-1', protected: false };

test('same organization alone is not authorization', () => {
  assert.equal(canDelete({ id: 'member', orgId: 'org-1', role: 'member', suspended: false }, target), false);
});

test('owner and admin are allowed on ordinary targets', () => {
  assert.equal(canDelete({ id: 'owner', orgId: 'org-1', role: 'member', suspended: false }, target), true);
  assert.equal(canDelete({ id: 'admin', orgId: 'org-2', role: 'admin', suspended: false }, target), true);
});

test('suspended actors are denied even when admin', () => {
  assert.equal(canDelete({ id: 'admin', role: 'admin', suspended: true }, target), false);
});

test('protected targets require admin', () => {
  const protectedTarget = { ...target, protected: true };
  assert.equal(canDelete({ id: 'owner', role: 'member', suspended: false }, protectedTarget), false);
  assert.equal(canDelete({ id: 'admin', role: 'admin', suspended: false }, protectedTarget), true);
});

test('malformed input fails closed', () => {
  assert.equal(canDelete(null, target), false);
  assert.equal(canDelete({ id: 'x' }, null), false);
});

