function planMigration(currentColumns, targetColumns, options = {}) {
  return {
    add: targetColumns.filter((name) => !currentColumns.includes(name)),
    drop: currentColumns.filter((name) => !targetColumns.includes(name))
  };
}

module.exports = { planMigration };

files.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const { planMigration } = require('./solution');

test('non-destructive additions are allowed', () => {
  assert.deepEqual(planMigration(['id'], ['id', 'email']), { add: ['email'], drop: [] });
});

test('destructive changes require both explicit gates', () => {
  assert.throws(() => planMigration(['id', 'legacy'], ['id']), /destructive|backup/i);
  assert.throws(() => planMigration(['id', 'legacy'], ['id'], { allowDestructive: true }), /backup/i);
  assert.throws(() => planMigration(['id', 'legacy'], ['id'], { backupConfirmed: true }), /destructive|allow/i);
  assert.deepEqual(
    planMigration(['id', 'legacy'], ['id'], { allowDestructive: true, backupConfirmed: true }),
    { add: [], drop: ['legacy'] }
  );
});

test('invalid schemas are rejected', () => {
  assert.throws(() => planMigration(['id', 'id'], ['id']), /unique|duplicate/i);
  assert.throws(() => planMigration(['id'], ['']), /column|non-empty|invalid/i);
});
